CREATE TABLE liquidaciones.liquidation_audit(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,batch_id uuid REFERENCES liquidaciones.liquidation_batches(batch_id),action text NOT NULL,entity_type text,entity_id text,details_json jsonb,created_at timestamptz NOT NULL,created_by text);
CREATE TABLE liquidaciones.migration_runs(run_id uuid PRIMARY KEY,source_path text NOT NULL,source_sha256 varchar(64) NOT NULL,status varchar(24) NOT NULL,started_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at timestamptz,report_json jsonb);
CREATE TABLE liquidaciones.migration_progress(run_id uuid NOT NULL REFERENCES liquidaciones.migration_runs(run_id) ON DELETE CASCADE,table_name text NOT NULL,last_key text,rows_copied bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(run_id,table_name));
